  Ltac err_tail_tac NV :=
    let NV2 := eval vm_compute in (NV + 32)%nat in
    intros vals R M VM A1 HL P0 P48 P3 P4 P5 HR HK HBR HH;
    pose proof Hsp as Hsp'; pose proof Hal as Hal';
